(function(){"use strict";var t,n,s=[{t:"关关雎鸠，在河之洲。窈窕淑女，君子好逑。",a:"佚名",s:"《诗经·周南·关雎》"},{t:"青青子衿，悠悠我心。纵我不往，子宁不嗣音？",a:"佚名",s:"《诗经·郑风·子衿》"},{t:"采采卷耳，不盈顷筐。嗟我怀人，寘彼周行。",a:"佚名",s:"《诗经·周南·卷耳》"},{t:"如切如磋，如琢如磨。",a:"佚名",s:"《诗经·卫风·淇奥》"},{t:"高山仰止，景行行止。",a:"佚名",s:"《诗经·小雅·车舝》"},{t:"路漫漫其修远兮，吾将上下而求索。",a:"屈原",s:"《离骚》"},{t:"日月忽其不淹兮，春与秋其代序。",a:"屈原",s:"《离骚》"},{t:"举世皆浊我独清，众人皆醉我独醒。",a:"屈原",s:"《渔父》"},{t:"秋风萧瑟天气凉，草木摇落露为霜。",a:"曹丕",s:"《燕歌行》"},{t:"青青园中葵，朝露待日晞。",a:"汉乐府",s:"《长歌行》"},{t:"江南可采莲，莲叶何田田。",a:"汉乐府",s:"《江南》"},{t:"采菊东篱下，悠然见南山。",a:"陶渊明",s:"《饮酒·其五》"},{t:"晨兴理荒秽，带月荷锄归。",a:"陶渊明",s:"《归园田居·其三》"},{t:"云想衣裳花想容，春风拂槛露华浓。",a:"李白",s:"《清平调·其一》"},{t:"花间一壶酒，独酌无相亲。",a:"李白",s:"《月下独酌》"},{t:"举杯邀明月，对影成三人。",a:"李白",s:"《月下独酌》"},{t:"床前明月光，疑是地上霜。",a:"李白",s:"《静夜思》"},{t:"大鹏一日同风起，扶摇直上九万里。",a:"李白",s:"《上李邕》"},{t:"长风破浪会有时，直挂云帆济沧海。",a:"李白",s:"《行路难》"},{t:"江畔何人初见月？江月何年初照人？",a:"张若虚",s:"《春江花月夜》"},{t:"人生代代无穷已，江月年年只相似。",a:"张若虚",s:"《春江花月夜》"},{t:"海上生明月，天涯共此时。",a:"张九龄",s:"《望月怀远》"},{t:"草木有本心，何求美人折？",a:"张九龄",s:"《感遇·其一》"},{t:"独在异乡为异客，每逢佳节倍思亲。",a:"王维",s:"《九月九日忆山东兄弟》"},{t:"大漠孤烟直，长河落日圆。",a:"王维",s:"《使至塞上》"},{t:"红豆生南国，春来发几枝。",a:"王维",s:"《相思》"},{t:"月落乌啼霜满天，江枫渔火对愁眠。",a:"张继",s:"《枫桥夜泊》"},{t:"野火烧不尽，春风吹又生。",a:"白居易",s:"《赋得古原草送别》"},{t:"天长地久有时尽，此恨绵绵无绝期。",a:"白居易",s:"《长恨歌》"},{t:"在天愿作比翼鸟，在地愿为连理枝。",a:"白居易",s:"《长恨歌》"},{t:"同是天涯沦落人，相逢何必曾相识。",a:"白居易",s:"《琵琶行》"},{t:"春蚕到死丝方尽，蜡炬成灰泪始干。",a:"李商隐",s:"《无题》"},{t:"夕阳无限好，只是近黄昏。",a:"李商隐",s:"《乐游原》"},{t:"曾经沧海难为水，除却巫山不是云。",a:"元稹",s:"《离思五首·其四》"},{t:"取次花丛懒回顾，半缘修道半缘君。",a:"元稹",s:"《离思五首·其四》"},{t:"人生自古谁无死？留取丹心照汗青。",a:"文天祥",s:"《过零丁洋》"},{t:"大江东去，浪淘尽，千古风流人物。",a:"苏轼",s:"《念奴娇·赤壁怀古》"},{t:"人生如梦，一尊还酹江月。",a:"苏轼",s:"《念奴娇·赤壁怀古》"},{t:"但愿人长久，千里共婵娟。",a:"苏轼",s:"《水调歌头·丙辰中秋》"},{t:"人有悲欢离合，月有阴晴圆缺，此事古难全。",a:"苏轼",s:"《水调歌头·丙辰中秋》"},{t:"十年生死两茫茫，不思量，自难忘。",a:"苏轼",s:"《江城子·乙卯正月二十日夜记梦》"},{t:"小轩窗，正梳妆。相顾无言，惟有泪千行。",a:"苏轼",s:"《江城子·乙卯正月二十日夜记梦》"},{t:"莫等闲，白了少年头，空悲切。",a:"岳飞",s:"《满江红·写怀》"},{t:"三十功名尘与土，八千里路云和月。",a:"岳飞",s:"《满江红·写怀》"},{t:"执手相看泪眼，竟无语凝噎。",a:"柳永",s:"《雨霖铃·寒蝉凄切》"},{t:"昨夜西风凋碧树，独上高楼，望尽天涯路。",a:"晏殊",s:"《蝶恋花·槛菊愁烟兰泣露》"},{t:"无可奈何花落去，似曾相识燕归来。",a:"晏殊",s:"《浣溪沙·一曲新词酒一杯》"},{t:"两情若是久长时，又岂在朝朝暮暮。",a:"秦观",s:"《鹊桥仙·纤云弄巧》"},{t:"古道西风瘦马，夕阳西下，断肠人在天涯。",a:"马致远",s:"《天净沙·秋思》"},{t:"泪眼问花花不语，乱红飞过秋千去。",a:"欧阳修",s:"《蝶恋花·庭院深深深几许》"},{t:"我劝天公重抖擞，不拘一格降人才。",a:"龚自珍",s:"《己亥杂诗·其二百二十》"},{t:"落红不是无情物，化作春泥更护花。",a:"龚自珍",s:"《己亥杂诗·其五》"},{t:"我自横刀向天笑，去留肝胆两昆仑。",a:"谭嗣同",s:"《狱中题壁》"},{t:"落霞与孤鹜齐飞，秋水共长天一色。",a:"王勃",s:"《滕王阁序》"},{t:"天苍苍，野茫茫，风吹草低见牛羊。",a:"北朝民歌",s:"《敕勒歌》"}],o=new Date,a=new Date(o.getFullYear(),0,0),r=Math.floor((o-a)/864e5),e=s[r%s.length],i=document.getElementById("quote-text");if(!i)return;i.textContent=e.t,t=document.getElementById("quote-author"),n=document.getElementById("quote-source"),t&&(t.textContent="—— "+e.a),n&&(n.textContent=e.s)})()